/** When the sheet's today changes, every open period whose to-date plus this many days is
 *  before the new today is closed; null when blank (off). */
@Column(name = "grace_days")
private Integer graceDays;

/** The month (1 to 12) the sheet's fiscal year starts in; 1 unless set. Not dated. */
@Column(name = "fiscal_start_month", nullable = false)
private int fiscalStartMonth = 1;

/** The pot shared out among each balanced pool's members by their shares; null when blank
 *  (none). Not dated. */
@Column(name = "pot")
private BigDecimal pot;

/** The id of the sheet's parent: a grade with no rate of its own in force on a date takes its
 *  parent's (then its parent's parent's, up to three levels up); null when blank (none). Not dated. */
@Column(name = "parent")
private String parent;

/** Whether a steward has archived the sheet: every change on it is refused. */
@Column(name = "archived", nullable = false)
private boolean archived;

protected Sheet() {
}

public Sheet(String id, String createdBy, LocalDate today) {
    this.id = id;
    this.createdBy = createdBy;
    this.today = today;
}

/** A clone of the sheet under another id, created by a user: its today and every setting (its
 *  dated settings, policy date, period numbering, entry date, grace days, fiscal start month, pot and parent). It is
 *  not archived and has given no claim number yet. */
public Sheet clonedTo(String id, String createdBy) {
    Sheet copy = new Sheet(id, createdBy, today);
    settings.forEach(d -> copy.settings.add(new DatedSetting(d.getKey(), d.getFrom(), d.getValue())));
    copy.policyDate = policyDate;
    copy.periodNumberingFrom = periodNumberingFrom;
    copy.entryDate = entryDate;
    copy.graceDays = graceDays;
    copy.fiscalStartMonth = fiscalStartMonth;
    copy.pot = pot;
    copy.parent = parent;
    return copy;
}

public String getId() {
    return id;
}
}

public void setFiscalStartMonth(int fiscalStartMonth) {
    this.fiscalStartMonth = fiscalStartMonth;
}

public BigDecimal getPot() {
    return pot;
}

public void setPot(BigDecimal pot) {
    this.pot = pot;
}

public String getParent() {
    return parent;
private static final String DELEGATION = "delegation";
private static final String PERMISSION = "permission";

/** The version an entity that was removed leaves. */
private static final String REMOVED = "null";

record SettingState(String key, LocalDate from, String value) {
}

record SheetState(LocalDate policyDate, List<SettingState> settings, LocalDate periodNumberingFrom,
        Integer graceDays, boolean archived, LocalDate entryDate, BigDecimal pot, Integer fiscalStartMonth) {
}

record GradeState(LocalDate from, String grade) {
}

record HoldState(LocalDate from, LocalDate to) {
}

record PersonState(String name, String grade, List<GradeState> grades, Integer terms, LocalDate retiredFrom,
        List<HoldState> holds, String contact, List<String> aliases, Long position,
}

/** Write the version of the sheet's settings now, if it differs from the last one. */
public void recordSheet(Sheet sheet) {
    List<SettingState> settings = sheet.getDatedSettings().values().stream()
            .flatMap(List::stream)
            .map(d -> new SettingState(d.getKey(), d.getFrom(), d.getValue()))
            .toList();
    write(sheet.getId(), SHEET, sheet.getId(), new SheetState(sheet.getPolicyDate(), settings,
            sheet.getPeriodNumberingFrom(), sheet.getGraceDays(), sheet.isArchived(), sheet.getEntryDate(),
            sheet.getPot(), sheet.getFiscalStartMonth()));
}

/** Write the version of an entity of the sheet now, if it differs from the last one. */
void record(Object entity) {
    if (entity instanceof Claim c) {
        if (state.equals(REMOVED)) {
            return;
        }
        String kind = key.substring(0, key.indexOf('/'));
        String id = key.substring(key.indexOf('/') + 1);
        switch (kind) {
            case SHEET -> {
                SheetState s = json.readValue(state, SheetState.class);
                sheet.setPolicyDate(s.policyDate());
                s.settings().forEach(d -> sheet.recordSetting(d.key(), d.from(), d.value()));
                sheet.setPeriodNumberingFrom(s.periodNumberingFrom());
                sheet.setGraceDays(s.graceDays());
                sheet.setEntryDate(s.entryDate());
                sheet.setPot(s.pot());
                sheet.setFiscalStartMonth(s.fiscalStartMonth() == null ? 1 : s.fiscalStartMonth());
                if (s.archived()) {
                    sheet.archive();
                }
            }
            case PERSON -> people.put(Long.valueOf(id), personOf(sheetId, Long.parseLong(id), json.readValue(state, PersonState.class)));
            case RATE -> {
    sheets.lock(sheetId);
    sheet.setFiscalStartMonth(month);
    sheets.flush();
    audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
            + " key=" + FISCAL_START_MONTH + " value=" + month);
    return month;
}

/** The sheet's pot; null when blank (none). */
@Transactional(readOnly = true)
public BigDecimal pot(String sheetId) {
    return sheets.find(sheetId).map(Sheet::getPot).orElse(null);
}

/** Set the sheet's pot (null: none), the sheet created first if it was never loaded; not dated. */
@Transactional
public BigDecimal setPot(String sheetId, String user, BigDecimal pot) {
    Sheet sheet = sheets.load(sheetId, user);
    sheets.lock(sheetId);
    BigDecimal scaled = pot == null ? null : pot.setScale(2);
    sheet.setPot(scaled);
    sheets.flush();
    audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
            + " key=" + POT + " value=" + (scaled == null ? "" : scaled.toPlainString()));
    return scaled;
}

/** The id of the sheet's parent; null when blank (none). */
@Transactional(readOnly = true)
public String parent(String sheetId) {
    return sheets.find(sheetId).map(Sheet::getParent).orElse(null);

